ld name="date_done" string="Effective Date" optional="hide"/>\n                    <field name="origin" optional="show" readonly="state in ['cancel', 'done']"/>\n                    <field name="backorder_id" optional="hide"/>\n                    <field name="picking_type_id" optional="hide"/>\n                    <field name="company_id" groups="base.group_multi_company" optional="show"/>\n                    <field name="state" optional="show" widget="badge" decoration-danger="state=='cancel'" decoration-info="state== 'assigned'" decoration-muted="state == 'draft'" decoration-success="state == 'done'" decoration-warning="state not in ('draft','cancel','done','assigned')"/>\n                    <field name="activity_exception_decoration" widget="activity_exception"/>\n                    <field name="json_popover" widget="stock_rescheduling_popover" nolabel="1" invisible="not json_popover"/>\n                </list>\n            	f	t	2025-09-29 21:49:49.241472	2025-09-29 21:49:49.241472	f
1123	12	\N	1	1	stock.picking.form	stock.picking	\N	form	stock/views/stock_picking_views.xml	primary	{"en_US": "<form string=\\"Transfer\\">\\n                <header>\\n                    <button name=\\"action_confirm\\" invisible=\\"state != 'draft'\\" string=\\"Mark as Todo\\" type=\\"object\\" class=\\"oe_highlight\\" groups=\\"base.group_user\\" data-hotkey=\\"q\\"/>\\n                    <button name=\\"action_assign\\" invisible=\\"not show_check_availability\\" string=\\"Check Availability\\" type=\\"object\\" class=\\"oe_highlight\\" groups=\\"base.group_user\\" data-hotkey=\\"w\\"/>\\n                    <button name=\\"button_validate\\" invisible=\\"state in ('draft', 'confirmed', 'done', 'cancel')\\" string=\\"Validate\\" type=\\"object\\" class=\\"oe_highlight\\" groups=\\"stock.group_stock_user\\" data-hotkey=\\"v\\"/>\\n                    <button name=\\"button_validate\\" invisible=\\"state in ('waiting', 'assigned', 'done', 'cancel')\\" string=\\"Validate\\" type=\\"object\\" groups=\\"stock.group_stock_user\\" class=\\"o_btn_validate\\" data-hotkey=\\"v\\"/>\\n                    <widget name=\\"signature\\" string=\\"Sign\\" highlight=\\"1\\" invisible=\\"not id or picking_type_code != 'outgoing' or state != 'done' or is_signed\\" full_name=\\"partner_id\\" groups=\\"stock.group_stock_sign_delivery\\"/>\\n                    <widget name=\\"signature\\" string=\\"Sign\\" invisible=\\"not id or picking_type_code != 'outgoing' or state == 'done' or is_signed\\" full_name=\\"partner_id\\" groups=\\"stock.group_stock_sign_delivery\\"/>\\n                    <button name=\\"do_print_picking\\" string=\\"Print\\" groups=\\"stock.group_stock_user\\" type=\\"object\\" invisible=\\"state != 'assigned'\\" data-hotkey=\\"o\\"/>\\n                    <button name=\\"357\\" string=\\"Print\\" invisible=\\"state != 'done'\\" type=\\"action\\" groups=\\"base.group_user\\" data-hotkey=\\"o\\"/>\\n                    <button name=\\"375\\" string=\\"Return\\" invisible=\\"state != 'done'\\" type=\\"action\\" groups=\\"base.group_user\\" data-hotkey=\\"k\\"/>\\n                    <field name=\\"state\\" widget=\\"statusbar\\" invisible=\\"picking_type_code != 'incoming'\\" statusbar_visible=\\"draft,assigned,done\\"/>\\n                    <field name=\\"state\\" widget=\\"statusbar\\" invisible=\\"picking_type_code == 'incoming'\\" statusbar_visible=\\"draft,confirmed,assigned,done\\"/>\\n                    <button name=\\"action_cancel\\" invisible=\\"state not in ('assigned', 'confirmed', 'draft', 'waiting')\\" string=\\"Cancel\\" groups=\\"base.group_user\\" type=\\"object\\" confirm=\\"Are you sure you want to cancel this transfer?\\" data-hotkey=\\"x\\"/>\\n                </header>\\n                <sheet>\\n                    <div class=\\"oe_button_box\\" name=\\"button_box\\">\\n                        <button name=\\"action_see_returns\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-rotate-left\\" invisible=\\"return_count == 0\\">\\n                            <field string=\\"Returns\\" name=\\"return_count\\" widget=\\"statinfo\\"/>\\n                        </button>\\n                        <button name=\\"action_see_move_scrap\\" string=\\"Scraps\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"oi-arrows-v\\" invisible=\\"not has_scrap_move\\"/>\\n                        <button name=\\"action_see_packages\\" string=\\"Packages\\" type=\\"object\\" class=\\"oe_stat_button\\" icon=\\"fa-cubes\\" invisible=\\"not has_packages\\"/>\\n                        <button name=\\"353\\" icon=\\"oi-arrow-up\\" class=\\"oe_stat_button\\" type=\\"action\\" invisible=\\"state != 'done' or not has_tracking\\" groups=\\"stock.group_production_lot\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Traceability</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_view_reception_report\\" type=\\"object\\" context=\\"{'default_picking_ids': [id]}\\" class=\\"oe_stat_button\\" icon=\\"fa-list\\" invisible=\\"not show_allocation\\" groups=\\"stock.group_reception_report\\">\\n                            <div class=\\"o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Allocation</span>\\n                            </div>\\n                        </button>\\n                        <!-- Use the following button to avoid onchange on one2many -->\\n                        <button name=\\"action_picking_move_tree\\" class=\\"oe_stat_button\\" icon=\\"oi-arrows-v\\" type=\\"object\\" help=\\"List view of operations\\" groups=\\"base.group_no_one\\" invisible=\\"(is_locked or state == 'done') or state == 'done' and is_locked\\" context=\\"{'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref':'stock.view_move_form', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id}\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Operations</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_detailed_operations\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" help=\\"List view of detailed operations\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Moves</span>\\n                            </div>\\n                        </button>\\n                        <button name=\\"action_next_transfer\\" class=\\"oe_stat_button\\" icon=\\"fa-exchange\\" type=\\"object\\" help=\\"List view of next transfers\\" invisible=\\"not show_next_pickings\\">\\n                            <div class=\\"o_form_field o_stat_info\\">\\n                                <span class=\\"o_stat_text\\">Next Transfer</span>\\n                            </div>\\n                        </button>\\n                    </div>\\n                    <div class=\\"oe_title\\">\\n                        <h1 class=\\"d-flex\\">\\n                            <field name=\\"priority\\" widget=\\"priority\\" class=\\"me-3\\"/>\\n                            <div invisible=\\"id\\">New <field name=\\"picking_type_code\\"/></div>\\n                            <field name=\\"name\\" invisible=\\"not id\\"/>\\n                        </h1>\\n                    </div>\\n                    <group>\\n                        <group>\\n                            <div class=\\"o_td_label\\">\\n                                <label for=\\"partner_id\\" string=\\"Delivery Address\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code != 'outgoing'\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Receive From\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code != 'incoming'\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Contact\\" style=\\"font-weight:bold;\\" invisible=\\"picking_type_code in ['incoming', 'outgoing']\\"/>\\n                            </div>\\n                            <field name=\\"partner_id\\" nolabel=\\"1\\" readonly=\\"state in ['cancel', 'done']\\" placeholder=\\"e.g. Lumber Inc\\"/>\\n                            <field name=\\"picking_type_id\\" options=\\"{'no_open': True}\\" readonly=\\"state in ('done', 'cancel')\\" domain=\\"[('code', 'in', ('incoming', 'outgoing', 'internal'))]\\"/>\\n                            <field name=\\"location_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_dest_id\\" groups=\\"!stock.group_stock_multi_locations\\" invisible=\\"1\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_id\\" options=\\"{'no_create': True}\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"picking_type_code == 'incoming'\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"location_dest_id\\" options=\\"{'no_create': True}\\" groups=\\"stock.group_stock_multi_locations\\" invisible=\\"picking_type_code == 'outgoing'\\" readonly=\\"state == 'done'\\"/>\\n                            <field name=\\"backorder_id\\" invisible=\\"not backorder_id\\"/>\\n                            <field name=\\"use_create_lots\\" invisible=\\"1\\"/> <!-- used by embedded stock.move list view below -->\\n                        </group>\\n                        <group>\\n                            <label for=\\"scheduled_date\\"/>\\n                            <div class=\\"o_row\\">\\n                                <field name=\\"scheduled_date\\" readonly=\\"state in ['cancel', 'done']\\" required=\\"id\\" decoration-warning=\\"state not in ('done', 'cancel') and scheduled_date &lt; now\\" decoration-danger=\\"state not in ('done', 'cancel') and scheduled_date &lt; current_date\\" decoration-bf=\\"state not in ('done', 'cancel') and (scheduled_date &lt; current_date or scheduled_date &lt; now)\\"/>\\n                                <field name=\\"json_popover\\" nolabel=\\"1\\" widget=\\"stock_rescheduling_popover\\" invisible=\\"not json_popover\\"/>\\n                            </div>\\n                            <field name=\\"date_deadline\\" invisible=\\"state in ('done', 'cancel') or not date_deadline\\" decoration-danger=\\"date_deadline and date_deadline &lt; current_date\\" decoration-bf=\\"date_deadline and date_deadline &lt; current_date\\"/>\\n                            <field name=\\"products_availability_state\\" invisible=\\"1\\"/>\\n                            <field name=\\"products_availability\\" invisible=\\"picking_type_code != 'outgoing' or state not in ['confirmed', 'waiting', 'assigned']\\" decoration-success=\\"state == 'assigned' or products_availability_state == 'available'\\" decoration-warning=\\"state != 'assigned' and products_availability_state in ('expected', 'available')\\" decoration-danger=\\"state != 'assigned' and products_availability_state == 'late'\\"/>\\n                            <field name=\\"date_done\\" string=\\"Effective Date\\" invisible=\\"state != 'done'\\"/>\\n                            <field name=\\"origin\\" placeholder=\\"e.g. PO0032\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                            <field name=\\"owner_id\\" groups=\\"stock.group_tracking_owner\\" invisible=\\"picking_type_code != 'incoming'\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                        </group>\\n                    </group>\\n                    <field name=\\"picking_properties\\" columns=\\"2\\"/>\\n                    <notebook>\\n                        <page string=\\"Operations\\" name=\\"operations\\">\\n                            <field name=\\"move_ids_without_package\\" mode=\\"list,kanban\\" widget=\\"stock_move_one2many\\" readonly=\\"state == 'done' and is_locked\\" context=\\"{'default_company_id': company_id, 'default_date': scheduled_date, 'default_date_deadline': date_deadline, 'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref': 'stock.view_stock_move_operations', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_partner_id': partner_id}\\" add-label=\\"Add a Product\\">\\n                                <list decoration-muted=\\"scrapped == True or state == 'cancel' or (state == 'done' and is_locked == True)\\" string=\\"Stock Moves\\" editable=\\"bottom\\">\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"name\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"state\\" readonly=\\"0\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_type_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"move_line_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"location_dest_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"partner_id\\" column_invisible=\\"True\\" readonly=\\"state == 'done'\\"/>\\n                                    <field name=\\"scrapped\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_code\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_details_visible\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"additional\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"move_lines_count\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_locked\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_uom_category_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_storable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"has_tracking\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_id\\" context=\\"{'default_is_storable': True}\\" required=\\"1\\" readonly=\\"(state != 'draft' and not additional) or move_lines_count &gt; 0\\" force_save=\\"1\\"/>\\n                                    <field name=\\"location_final_id\\" optional=\\"hide\\" groups=\\"stock.group_stock_multi_locations\\"/>\\n                                    <field name=\\"description_picking\\" string=\\"Description\\" optional=\\"hide\\"/>\\n                                    <field name=\\"date\\" optional=\\"hide\\"/>\\n                                    <field name=\\"date_deadline\\" optional=\\"hide\\"/>\\n                                    <field name=\\"is_quantity_done_editable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_quant\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_lots_text\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"show_lots_m2o\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"is_initial_demand_editable\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"display_import_lot\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picking_type_entire_packs\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"product_packaging_id\\" groups=\\"product.group_stock_packaging\\" context=\\"{'default_product_id': product_id}\\" readonly=\\"not product_id\\"/>\\n                                    <field name=\\"product_uom_qty\\" string=\\"Demand\\" readonly=\\"not is_initial_demand_editable\\"/>\\n                                    <button type=\\"object\\" name=\\"action_product_forecast_report\\" title=\\"Forecast Report\\" icon=\\"fa-area-chart\\" invisible=\\"not product_id or product_uom_qty == 0 or quantity == 0 and forecast_availability &lt;= 0 or (parent.picking_type_code == 'outgoing' and state != 'draft')\\"/>\\n                                    <button type=\\"object\\" name=\\"action_product_forecast_report\\" title=\\"Forecast Report\\" icon=\\"fa-area-chart text-danger\\" invisible=\\"not product_id or product_uom_qty == 0 or quantity &gt; 0 or forecast_availability &gt; 0 or (parent.picking_type_code == 'outgoing' and state != 'draft')\\"/>\\n                                    <field name=\\"forecast_expected_date\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"forecast_availability\\" string=\\"Forecast\\" optional=\\"hide\\" column_invisible=\\"parent.state in ('draft', 'done') or parent.picking_type_code != 'outgoing'\\" widget=\\"forecast_widget\\"/>\\n                                    <field name=\\"product_qty\\" readonly=\\"1\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"quantity\\" string=\\"Quantity\\" readonly=\\"not is_quantity_done_editable\\" column_invisible=\\"parent.state=='draft'\\" decoration-danger=\\"product_uom_qty and quantity &gt; product_uom_qty and parent.state not in ['done', 'cancel']\\"/>\\n                                    <field name=\\"product_uom\\" readonly=\\"state != 'draft' and not additional\\" options=\\"{'no_open': True, 'no_create': True}\\" string=\\"Unit\\" groups=\\"uom.group_uom\\"/>\\n                                    <field name=\\"product_uom\\" groups=\\"!uom.group_uom\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"picked\\" optional=\\"hide\\" column_invisible=\\"parent.state=='draft'\\"/>\\n                                    <field name=\\"lot_ids\\" widget=\\"many2many_tags\\" column_invisible=\\"parent.state == 'draft'\\" groups=\\"stock.group_production_lot\\" invisible=\\"not show_details_visible or has_tracking == 'none'\\" optional=\\"hide\\" options=\\"{'create': [('parent.use_create_lots', '=', True)]}\\" context=\\"{'default_company_id': company_id, 'default_product_id': product_id, 'active_picking_id': parent.id}\\" domain=\\"[('product_id','=',product_id)]\\"/>\\n                                </list>\\n                            </field>\\n                            <field name=\\"id\\" invisible=\\"1\\"/>\\n                            <field name=\\"package_level_ids\\" context=\\"{'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_company_id': company_id}\\" invisible=\\"not picking_type_entire_packs\\" readonly=\\"state == 'done'\\"/>\\n                            <button class=\\"btn-secondary float-end\\" name=\\"action_put_in_pack\\" type=\\"object\\" string=\\"Put in Pack\\" invisible=\\"state in ('draft', 'done', 'cancel')\\" groups=\\"stock.group_tracking_lot\\" data-hotkey=\\"shift+g\\"/>\\n                        </page>\\n                        <page string=\\"Additional Info\\" name=\\"extra\\">\\n                            <group>\\n                                <group string=\\"Other Information\\" name=\\"other_infos\\">\\n                                    <field name=\\"picking_type_code\\" invisible=\\"1\\"/>\\n                                    <field name=\\"move_type\\" invisible=\\"picking_type_code == 'incoming'\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" domain=\\"[('share', '=', False)]\\" readonly=\\"state in ['cancel', 'done']\\"/>\\n                                    <field name=\\"group_id\\" groups=\\"base.group_no_one\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" force_save=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Note\\" name=\\"note\\">\\n                            <field name=\\"note\\" string=\\"Note\\" placeholder=\\"Add an internal note that will be printed on the Picking Operations sheet\\"/>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Transfer">\n                <header>\n                    <button name="action_confirm" invisible="state != 'draft'" string="Mark as Todo" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="q"/>\n                    <button name="action_assign" invisible="not show_check_availability" string="Check Availability" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="w"/>\n                    <button name="button_validate" invisible="state in ('draft', 'confirmed', 'done', 'cancel')" string="Validate" type="object" class="oe_highlight" groups="stock.group_stock_user" data-hotkey="v"/>\n                    <button name="button_validate" invisible="state in ('waiting', 'assigned', 'done', 'cancel')" string="Validate" type="object" groups="stock.group_stock_user" class="o_btn_validate" data-hotkey="v"/>\n                    <widget name="signature" string="Sign" highlight="1" invisible="not id or picking_type_code != 'outgoing' or state != 'done' or is_signed" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>\n                    <widget name="signature" string="Sign" invisible="not id or picking_type_code != 'outgoing' or state == 'done' or is_signed" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>\n                    <button name="do_print_picking" string="Print" groups="stock.group_stock_user" type="object" invisible="state != 'assigned'" data-hotkey="o"/>\n                    <button name="357" string="Print" invisible="state != 'done'" type="action" groups="base.group_user" data-hotkey="o"/>\n                    <button name="375" string="Return" invisible="state != 'done'" type="action" groups="base.group_user" data-hotkey="k"/>\n                    <field name="state" widget="statusbar" invisible="picking_type_code != 'incoming'" statusbar_visible="draft,assigned,done"/>\n                    <field name="state" widget="statusbar" invisible="picking_type_code == 'incoming'" statusbar_visible="draft,confirmed,assigned,done"/>\n                    <button name="action_cancel" invisible="state not in ('assigned', 'confirmed', 'draft', 'waiting')" string="Cancel" groups="base.group_user" type="object" confirm="Are you sure you want to cancel this transfer?" data-hotkey="x"/>\n                </header>\n                <sheet>\n                    <div class="oe_button_box" name="button_box">\n                        <button name="action_see_returns" type="object" class="oe_stat_button" icon="fa-rotate-left" invisible="return_count == 0">\n                            <field string="Returns" name="return_count" widget="statinfo"/>\n                        </button>\n                        <button name="action_see_move_scrap" string="Scraps" type="object" class="oe_stat_button" icon="oi-arrows-v" invisible="not has_scrap_move"/>\n                        <button name="action_see_packages" string="Packages" type="object" class="oe_stat_button" icon="fa-cubes" invisible="not has_packages"/>\n                        <button name="353" icon="oi-arrow-up" class="oe_stat_button" type="action" invisible="state != 'done' or not has_tracking" groups="stock.group_production_lot">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Traceability</span>\n                            </div>\n                        </button>\n                        <button name="action_view_reception_report" type="object" context="{'default_picking_ids': [id]}" class="oe_stat_button" icon="fa-list" invisible="not show_allocation" groups="stock.group_reception_report">\n                            <div class="o_stat_info">\n                                <span class="o_stat_text">Allocation</span>\n                            </div>\n                        </button>\n                        <!-- Use the following button to avoid onchange on one2many -->\n                        <button name="action_picking_move_tree" class="oe_stat_button" icon="oi-arrows-v" type="object" help="List view of operations" groups="base.group_no_one" invisible="(is_locked or state == 'done') or state == 'done' and is_locked" context="{'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref':'stock.view_move_form', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id}">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Operations</span>\n                            </div>\n                        </button>\n                        <button name="action_detailed_operations" class="oe_stat_button" icon="fa-bars" type="object" help="List view of detailed operations">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Moves</span>\n                            </div>\n                        </button>\n                        <button name="action_next_transfer" class="oe_stat_button" icon="fa-exchange" type="object" help="List view of next transfers" invisible="not show_next_pickings">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Next Transfer</span>\n                            </div>\n                        </button>\n                    </div>\n                    <div class="oe_title">\n                        <h1 class="d-flex">\n                            <field name="priority" widget="priority" class="me-3"/>\n                            <div invisible="id">New <field name="picking_type_code"/></div>\n                            <field name="name" invisible="not id"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <div class="o_td_label">\n                                <label for="partner_id" string="Delivery Address" style="font-weight:bold;" invisible="picking_type_code != 'outgoing'"/>\n                                <label for="partner_id" string="Receive From" style="font-weight:bold;" invisible="picking_type_code != 'incoming'"/>\n                                <label for="partner_id" string="Contact" style="font-weight:bold;" invisible="picking_type_code in ['incoming', 'outgoing']"/>\n                            </div>\n                            <field name="partner_id" nolabel="1" readonly="state in ['cancel', 'done']" placeholder="e.g. Lumber Inc"/>\n                            <field name="picking_type_id" options="{'no_open': True}" readonly="state in ('done', 'cancel')" domain="[('code', 'in', ('incoming', 'outgoing', 'internal'))]"/>\n                            <field name="location_id" groups="!stock.group_stock_multi_locations" invisible="1" readonly="state == 'done'"/>\n                            <field name="location_dest_id" groups="!stock.group_stock_multi_locations" invisible="1" readonly="state == 'done'"/>\n                            <field name="location_id" options="{'no_create': True}" groups="stock.group_stock_multi_locations" invisible="picking_type_code == 'incoming'" readonly="state == 'done'"/>\n                            <field name="location_dest_id" options="{'no_create': True}" groups="stock.group_stock_multi_locations" invisible="picking_type_code == 'outgoing'" readonly="state == 'done'"/>\n                            <field name="backorder_id" invisible="not backorder_id"/>\n                            <field name="use_create_lots" invisible="1"/> <!-- used by embedded stock.move list view below -->\n                        </group>\n                        <group>\n                            <label for="scheduled_date"/>\n                            <div class="o_row">\n                                <field name="scheduled_date" readonly="state in ['cancel', 'done']" required="id" decoration-warning="state not in ('done', 'cancel') and scheduled_date &lt; now" decoration-danger="state not in ('done', 'cancel') and scheduled_date &lt; current_date" decoration-bf="state not in ('done', 'cancel') and (scheduled_date &lt; current_date or scheduled_date &lt; now)"/>\n                                <field name="json_popover" nolabel="1" widget="stock_rescheduling_popover" invisible="not json_popover"/>\n                            </div>\n                            <field name="date_deadline" invisible="state in ('done', 'cancel') or not date_deadline" decoration-danger="date_deadline and date_deadline &lt; current_date" decoration-bf="date_deadline and date_deadline &lt; current_date"/>\n                            <field name="products_availability_state" invisible="1"/>\n                            <field name="products_availability" invisible="picking_type_code != 'outgoing' or state not in ['confirmed', 'waiting', 'assigned']" decoration-success="state == 'assigned' or products_availability_state == 'available'" decoration-warning="state != 'assigned' and products_availability_state in ('expected', 'available')" decoration-danger="state != 'assigned' and products_availability_state == 'late'"/>\n                            <field name="date_done" string="Effective Date" invisible="state != 'done'"/>\n                            <field name="origin" placeholder="e.g. PO0032" readonly="state in ['cancel', 'done']"/>\n                            <field name="owner_id" groups="stock.group_tracking_owner" invisible="picking_type_code != 'incoming'" readonly="state in ['cancel', 'done']"/>\n                        </group>\n                    </group>\n                    <field name="picking_properties" columns="2"/>\n                    <notebook>\n                        <page string="Operations" name="operations">\n                            <field name="move_ids_without_package" mode="list,kanban" widget="stock_move_one2many" readonly="state == 'done' and is_locked" context="{'default_company_id': company_id, 'default_date': scheduled_date, 'default_date_deadline': date_deadline, 'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref': 'stock.view_stock_move_operations', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_partner_id': partner_id}" add-label="Add a Product">\n                                <list decoration-muted="scrapped == True or state == 'cancel' or (state == 'done' and is_locked == True)" string="Stock Moves" editable="bottom">\n                                    <field name="company_id" column_invisible="True"/>\n                                    <field name="picking_id" column_invisible="True"/>\n                                    <field name="name" column_invisible="True"/>\n                                    <field name="state" readonly="0" column_invisible="True"/>\n                                    <field name="picking_type_id" column_invisible="True"/>\n                                    <field name="move_line_ids" column_invisible="True"/>\n                                    <field name="location_id" column_invisible="True"/>\n                                    <field name="location_dest_id" column_invisible="True"/>\n                                    <field name="partner_id" column_invisible="True" readonly="state == 'done'"/>\n                                    <field name="scrapped" column_invisible="True"/>\n                                    <field name="picking_code" column_invisible="True"/>\n                                    <field name="show_details_visible" column_invisible="True"/>\n                                    <field name="additional" column_invisible="True"/>\n                                    <field name="move_lines_count" column_invisible="True"/>\n                                    <field name="is_locked" column_invisible="True"/>\n                                    <field name="product_uom_category_id" column_invisible="True"/>\n                                    <field name="is_storable" column_invisible="True"/>\n                                    <field name="has_tracking" column_invisible="True"/>\n                                    <field name="product_id" context="{'default_is_storable': True}" required="1" readonly="(state != 'draft' and not additional) or move_lines_count &gt; 0" force_save="1"/>\n                                    <field name="location_final_id" optional="hide" groups="stock.group_stock_multi_locations"/>\n                                    <field name="description_picking" string="Description" optional="hide"/>\n                                    <field name="date" optional="hide"/>\n                                    <field name="date_deadline" optional="hide"/>\n                                    <field name="is_quantity_done_editable" column_invisible="True"/>\n                                    <field name="show_quant" column_invisible="True"/>\n                                    <field name="show_lots_text" column_invisible="True"/>\n                                    <field name="show_lots_m2o" column_invisible="True"/>\n                                    <field name="is_initial_demand_editable" column_invisible="True"/>\n                                    <field name="display_import_lot" column_invisible="True"/>\n                                    <field name="picking_type_entire_packs" column_invisible="True"/>\n                                    <field name="product_packaging_id" groups="product.group_stock_packaging" context="{'default_product_id': product_id}" readonly="not product_id"/>\n                                    <field name="product_uom_qty" string="Demand" readonly="not is_initial_demand_editable"/>\n                                    <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="fa-area-chart" invisible="not product_id or product_uom_qty == 0 or quantity == 0 and forecast_availability &lt;= 0 or (parent.picking_type_code == 'outgoing' and state != 'draft')"/>\n                                    <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="fa-area-chart text-danger" invisible="not product_id or product_uom_qty == 0 or quantity &gt; 0 or forecast_availability &gt; 0 or (parent.picking_type_code == 'outgoing' and state != 'draft')"/>\n                                    <field name="forecast_expected_date" column_invisible="True"/>\n                                    <field name="forecast_availability" string="Forecast" optional="hide" column_invisible="parent.state in ('draft', 'done') or parent.picking_type_code != 'outgoing'" widget="forecast_widget"/>\n                                    <field name="product_qty" readonly="1" column_invisible="True"/>\n                                    <field name="quantity" string="Quantity" readonly="not is_quantity_done_editable" column_invisible="parent.state=='draft'" decoration-danger="product_uom_qty and quantity &gt; product_uom_qty and parent.state not in ['done', 'cancel']"/>\n                                    <field name="product_uom" readonly="state != 'draft' and not additional" options="{'no_open': True, 'no_create': True}" string="Unit" groups="uom.group_uom"/>\n                                    <field name="product_uom" groups="!uom.group_uom" column_invisible="True"/>\n                                    <field name="picked" optional="hide" column_invisible="parent.state=='draft'"/>\n                                    <field name="lot_ids" widget="many2many_tags" column_invisible="parent.state == 'draft'" groups="stock.group_production_lot" invisible="not show_details_visible or has_tracking == 'none'" optional="hide" options="{'create': [('parent.use_create_lots', '=', True)]}" context="{'default_company_id': company_id, 'default_product_id': product_id, 'active_picking_id': parent.id}" domain="[('product_id','=',product_id)]"/>\n                                </list>\n                            </field>\n                            <field name="id" invisible="1"/>\n                            <field name="package_level_ids" context="{'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_company_id': company_id}" invisible="not picking_type_entire_packs" readonly="state == 'done'"/>\n                            <button class="btn-secondary float-end" name="action_put_in_pack" type="object" string="Put in Pack" invisible="state in ('draft', 'done', 'cancel')" groups="stock.group_tracking_lot" data-hotkey="shift+g"/>\n                        </page>\n                        <page string="Additional Info" name="extra">\n                            <group>\n                                <group string="Other Information" name="other_infos">\n                                    <field name="picking_type_code" invisible="1"/>\n                                    <field name="move_type" invisible="picking_type_code == 'incoming'" readonly="state in ['cancel', 'done']"/>\n                                    <field name="user_id" widget="many2one_avatar_user" domain="[('share', '=', False)]" readonly="state in ['cancel', 'done']"/>\n                                    <field name="group_id" groups="base.group_no_one"/>\n                                    <field name="company_id" groups="base.group_multi_company" options="{'no_create': True}" force_save="1"/>\n                                </group>\n                            </group>\n                        </page>\n                        <page string="Note" name="note">\n                            <field name="note" string="Note" placeholder="Add an internal note that will be printed on the Picking Operations sheet"/>\n                        </page>\n                    </notebook>\n                </sheet>\n                <chatter/>\n                </form>\n            	f	t	2025-09-29 21:49:49.241472	2025-09-29 21:49:49.241472	f
1124	16	\N	1	1	stock.picking.internal.search	stock.picking	\N	search	stock/views/stock_picking_views.xml	primary	{"en_US": "<search string=\\"Picking Lists\\">\\n                    <field name=\\"name\\" string=\\"Transfer\\" filter_domain=\\"['|', ('name', 'ilike', self), ('origin', 'ilike', self)]\\"/>\\n                    <field name=\\"partner_id\\" filter_domain=\\"[('partner_id', 'child_of', self)]\\"/>\\n                    <field name=\\"origin\\"/>\\n                    <field name=\\"product_id\\"/>\\n                    <field name=\\"picking_type_id\\"/>\\n                    <field name=\\"move_line_ids\\" string=\\"Package\\" filter_domain=\\"['|', ('move_line_ids.package_id.name', 'ilike', self), ('move_line_ids.result_package_id.name', 'ilike', self)]\\" groups=\\"stock.group_tracking_lot\\"/>\\n                    <field name=\\"lot_id\\" groups=\\"stock.group_production_lot\\"/>\\n                    <filter name=\\"to_do_transfers\\" string=\\"To Do\\" domain=\\"['&amp;',('user_id', 'in', [uid, False]),('state','not in',['done','cancel'])]\\"/>\\n                    <filter name=\\"my_transfers\\" string=\\"My Transfers\\" domain=\\"[('user_id', '=', uid)]\\"/>\\n                    <filter string=\\"Starred\\" name=\\"starred\\" domain=\\"[('priority', '=', '1')]\\"/>\\n                    <separator/>\\n                    <filter name=\\"draft\\" string=\\"Draft\\" domain=\\"[('state', '=', 'draft')]\\" help=\\"Draft Moves\\"/>\\n                    <filter name=\\"waiting\\" string=\\"Waiting\\" domain=\\"[('state', 'in', ('confirmed', 'waiting'))]\\" help=\\"Waiting Moves\\"/>\\n                    <filter name=\\"available\\" string=\\"Ready\\" domain=\\"[('state', '=', 'assigned')]\\" help=\\"Assigned Moves\\"/>\\n                    <separator/>\\n                    <filter name=\\"reception\\" string=\\"Receipts\\" domain=\\"[('picking_type_code', '=', 'incoming')]\\"/>\\n                    <filter name=\\"delivery\\" string=\\"Deliveries\\" domain=\\"[('picking_type_code', '=', 'outgoing')]\\"/>\\n                    <filter name=\\"internal\\" string=\\"Internal\\" domain=\\"[('picking_type_code', '=', 'internal')]\\"/>\\n                    <separator/>\\n                    <filter invisible=\\"1\\" name=\\"before\\" string=\\"Before\\" domain=\\"[('search_date_category', '=', 'before')]\\"/>\\n                    <filter invisible=\\"1\\" name=\\"yesterday\\" string=\\"Yesterday\\" domain=\\"[('search_date_category', '=', 'yesterday')]\\"/>\\n                    <filter invisible=\\"1\\" name=\\"today\\" string=\\"Today\\" domain=\\"[('search_date_category', '=', 'today')]\\"/>\\n                    <filter invisible=\\"1\\" name=\\"day_1\\" string=\\"Tomorrow\\" domain=\\"[('search_date_category', '=', 'day_1')]\\"/>\\n                    <filter invisible=\\"1\\" name=\\"day_2\\" string=\\"The day after tomorrow\\" domain=\\"[('search_date_category', '=', 'day_2')]\\"/>\\n                    <filter invisible=\\"1\\" name=\\"after\\" string=\\"After\\" domain=\\"[('search_date_category', '=', 'after')]\\"/>\\n                    <filter name=\\"late\\" string=\\"Late\\" help=\\"Deadline exceed or/and by the scheduled\\" domain=\\"[('state', 'in', ('assigned', 'waiting', 'confirmed')), '|', '|', ('has_deadline_issue', '=', True), ('date_deadline', '&lt;', current_date), ('scheduled_date', '&lt;', current_date)]\\"/>\\n                    <filter string=\\"Planning Issues\\" name=\\"planning_issues\\" help=\\"Transfers that are late on scheduled time or one of pickings will be late\\" domain=\\"['|', ('delay_alert_date', '!=', False), '&amp;', ('scheduled_date','&lt;', time.strftime('%Y-%m-%d %H:%M:%S')), ('state', 'in', ('assigned', 'waiting', 'confirmed'))]\\"/>\\n                    <filter string=\\"Late Availability\\" name=\\"late_availability\\" domain=\\"[('products_availability_state', '=', 'late')]\\"/>\\n                    <separator/>\\n                    <filter name=\\"backorder\\" string=\\"Backorders\\" domain=\\"[('backorder_id', '!=', False), ('state', 'in', ('assigned', 'waiting', 'confirmed'))]\\" help=\\"Remaining parts of picking partially processed\\"/>\\n                    <separator/>\\n                    <filter invisible=\\"1\\" string=\\"Late Activities\\" name=\\"activities_overdue\\" domain=\\"[('my_activity_date_deadline', '&lt;', context_today().strftime('%Y-%m-%d'))]\\" help=\\"Show all records which has next action date is before today\\"/>\\n                    <filter invisible=\\"1\\" string=\\"Today Activities\\" name=\\"activities_today\\" domain=\\"[('my_activity_date_deadline', '=', context_today().strftime('%Y-%m-%d'))]\\"/>\\n                    <filter invisible=\\"1\\" string=\\"Future Activities\\" name=\\"activities_upcoming_all\\" domain=\\"[('my_activity_date_deadline', '&gt;', context_today().strftime('%Y-%m-%d'))]\\"/>\\n                    <separator/>\\n                    <filter string=\\"Warnings\\" name=\\"activities_exception\\" domain=\\"[('activity_exception_decoration', '!=', False)]\\"/>\\n                    <group expand=\\"0\\" string=\\"Group By\\">\\n                        <filter string=\\"Status\\" name=\\"status\\" domain=\\"[]\\" context=\\"{'group_by': 'state'}\\"/>\\n                        <filter string=\\"Scheduled Date\\" name=\\"expected_date\\" domain=\\"[]\\" context=\\"{'group_by': 'scheduled_date'}\\"/>\\n                        <filter string=\\"Source Document\\" name=\\"origin\\" domain=\\"[]\\" context=\\"{'group_by': 'origin'}\\"/>\\n                        <filter string=\\"Operation Type\\" name=\\"picking_type\\" domain=\\"[]\\" context=\\"{'group_by': 'picking_type_id'}\\"/>\\n                    </group>\\n                </search>"}	<?xml version="1.0"?>\n<search string="Picking Lists">\n                    <field name="name" string="Transfer" filter_domain="['|', ('name', 'ilike', self), ('origin', 'ilike', self)]"/>\n                    <field name="partner_id" filter_domain="[('partner_id', 'child_of', self)]"/>\n                    <field name="origin"/>\n                    <field name="product_id"/>\n                    <field name="picking_type_id"/>\n                    <field name="move_line_ids" string="Package" filter_domain="['|', ('move_line_ids.package_id.name', 'ilike', self), ('move_line_ids.result_package_id.name', 'ilike', self)]" groups="stock.group_tracking_lot"/>\n                    <field name="lot_id" groups="stock.group_production_lot"/>\n                    <filter name="to_do_transfers" string="To Do" domain="['&amp;',('user_id', 'in', [uid, False]),('state','not in',['done','cancel'])]"/>\n                    <filter name="my_transfers" string="My Transfers" domain="[('user_id', '=', uid)]"/>\n                    <filter string="Starred" name="starred" domain="[('priority', '=', '1')]"/>\n                    <separator/>\n                    <filter name="draft" string="Draft" domain="[('state', '=', 'draft')]" help="Draft Moves"/>\n                    <filter name="waiting" string="Waiting" domain="[('state', 'in', ('confirmed', 'waiting'))]" help="Waiting Moves"/>\n                    <filter name="available" string="Ready" domain="[('state', '=', 'assigned')]" help="Assigned Moves"/>\n                    <separator/>\n                    <filter name="reception" string="Receipts" domain="[('picking_type_code', '=', 'incoming')]"/>\n                    <filter name="delivery" string="Deliveries" domain="[('picking_type_code', '=', 'outgoing')]"/>\n                    <filter name="internal" string="Internal" domain="[('picking_type_code', '=', 'internal')]"/>\n                    <separator/>\n                    <filter invisible="1" name="before" string="Before" domain="[('search_date_category', '=', 'before')]"/>\n                    <filter invisible="1" name="yesterday" string="Yesterday" domain="[('search_date_category', '=', 'yesterday')]"/>\n                    <filter invisible="1" name="today" string="Today" domain="[('search_date_category', '=', 'today')]"/>\n                    <filter invisible="1" name="day_1" string="Tomorrow" domain="[('search_date_category', '=', 'day_1')]"/>\n                    <filter invisible="1" name="day_2" string="The day after tomorrow" domain="[('search_date_category', '=', 'day_2')]"/>\n                    <filter invisible="1" name="after" string="After" domain="[('search_date_category', '=', 'after')]"/>\n                    <filter name="late" string="Late" help="Deadline exceed or/and by the scheduled" domain="[('state', 'in', ('assigned', 'waiting', 'confirmed')), '|', '|', ('has_deadline_issue', '=', True), ('date_deadline', '&lt;', current_date), ('scheduled_date', '&lt;', current_date)]"/>\n                    <filter string="Planning Issues" name="planning_issues" help="Transfers that are late on scheduled time or one of pickings will be late" domain="['|', ('delay_alert_date', '!=', False), '&amp;', ('scheduled_date','&lt;', time.strftime('%Y-%m-%d %H:%M:%S')), ('state', 'in', ('assigned', 'waiting', 'confirmed'))]"/>\n                    <filter string="Late Availability" name="late_availability" domain="[('products_availability_state', '=', 'late')]"/>\n                    <separator/>\n                    <filter name="backorder" string="Backorders" domain="[('backorder_id', '!=', False), ('state', 'in', ('assigned', 'waiting', 'confirmed'))]" help="Remaining parts of picking partially processed"/>\n                    <separator/>\n                    <filter invisible="1" string="Late Activities" name="activities_overdue" domain="[('my_activity_date_deadline', '&lt;', context_today().strftime('%Y-%m-%d'))]" help="Show all records which has next action date is before today"/>\n                    <filter invisible="1" string="Today Activities" name="activities_today" domain="[('my_activity_date_deadline', '=', context_today().strftime('%Y-%m-%d'))]"/>\n                    <filter invisible